<?php function field($name,$label,$type='text',$required=true){$old=$_SESSION['_old'][$name]??'';$err=$_SESSION['_errors'][$name]??'';echo '<div class="col-md-4"><label class="form-label">'.e($label).'</label><input class="form-control '.($err?'is-invalid':'').'" type="'.e($type).'" name="'.e($name).'" value="'.e($old).'" '.($required?'required':'').'><div class="invalid-feedback">'.e($err).'</div></div>';} ?>
